export const RuntimeRequirementsSchema = z.object({
    min_runtime_version: z.string().trim().min(1).optional(),
    required_capabilities: z.array(z.string().trim().min(1)).min(1).refine((capabilities) => new Set(capabilities).size === capabilities.length, { message: 'required_capabilities must contain unique values' }).optional(),
});
export const TransitionSchema = z.union([
    z.string(),
    z.object({
        target: z.string(),
        guard: z.string().optional(),
        guardFunction: z.string().optional(),
        judgment: JudgmentDefinitionSchema.optional(),
        description: z.string().optional(),
